// Typed files
// Write 10 numbers to file, on next run - read these numbers and delete file
const filename = 'a.dat';

var f: file of integer;

begin
  if not FileExists(filename) then
  begin
    assign(f,filename);
    rewrite(f);
    writeln('Writing to file ',filename);
    for var i:=1 to 10 do
    begin
      var x := random(100); 
      write(x,' ');
      write(f,x);
    end;  
    close(f);  
  end
  else 
  begin
    assign(f,filename);
    reset(f);
    writeln('Reading from file ',filename);
    for var i:=1 to 10 do
    begin
      var x: integer;
      read(f,x);
      write(x,' ');
    end;  
    close(f);  
    erase(f);
  end;  
end.

// Generic functions
// Type T inference from parameter types

function IndexOf<T>(a: array of T; val: T): integer;
begin
  Result := -1;
  for var i:=0 to a.Length-1 do
    if a[i]=val then
    begin
      Result := i;
      exit;
    end;
end;

